de978afd Fixes bould free in opt_cleanup
 optimize.c | 33 +++++++++++++++++++++++++++------
 1 file changed, 27 insertions(+), 6 deletions(-)
commit de978afd02065649222988833063998b5e0dfc84
Author: Philippe Antoine <contact@catenacyber.fr>
Date:   Sat Jun 15 15:54:03 2019 +0200

    Fixes bould free in opt_cleanup

    (cherry picked from commit 3a48c915ea98a60fbac94522202279f56c740487)

diff --git a/optimize.c b/optimize.c
index 3b218fcd..5aa94d7d 100644
--- a/optimize.c
+++ b/optimize.c
@@ -2029,12 +2029,18 @@ intern_blocks(opt_state_t *opt_state, struct icode *ic)
 static void
 opt_cleanup(opt_state_t *opt_state)
 {
-       free((void *)opt_state->vnode_base);
-       free((void *)opt_state->vmap);
-       free((void *)opt_state->edges);
-       free((void *)opt_state->space);
-       free((void *)opt_state->levels);
-       free((void *)opt_state->blocks);
+       if (opt_state->vnode_base)
+               free((void *)opt_state->vnode_base);
+       if (opt_state->vmap)
+               free((void *)opt_state->vmap);
+       if (opt_state->edges)
+               free((void *)opt_state->edges);
+       if (opt_state->space)
+               free((void *)opt_state->space);
+       if (opt_state->levels)
+               free((void *)opt_state->levels);
+       if (opt_state->blocks)
+               free((void *)opt_state->blocks);
 }

 /*
@@ -2161,6 +2167,7 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
        opt_state->edges = (struct edge **)calloc(opt_state->n_edges, sizeof(*opt_state->edges));
        if (opt_state->edges == NULL) {
                free(opt_state->blocks);
+               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }

@@ -2171,6 +2178,8 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
        if (opt_state->levels == NULL) {
                free(opt_state->edges);
                free(opt_state->blocks);
+               opt_state->edges = NULL;
+               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }

@@ -2184,6 +2193,9 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
                free(opt_state->levels);
                free(opt_state->edges);
                free(opt_state->blocks);
+               opt_state->levels = NULL;
+               opt_state->edges = NULL;
+               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }
        p = opt_state->space;
@@ -2227,6 +2239,10 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
                free(opt_state->levels);
                free(opt_state->edges);
                free(opt_state->blocks);
+               opt_state->space = NULL;
+               opt_state->levels = NULL;
+               opt_state->edges = NULL;
+               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }
        opt_state->vnode_base = (struct valnode *)calloc(opt_state->maxval, sizeof(*opt_state->vnode_base));
@@ -2236,6 +2252,11 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
                free(opt_state->levels);
                free(opt_state->edges);
                free(opt_state->blocks);
+               opt_state->vmap = NULL;
+               opt_state->space = NULL;
+               opt_state->levels = NULL;
+               opt_state->edges = NULL;
+               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }
 }
commit 4c86c4eca3c1cae965764ce4321d501d511b2d15
Author: Philippe Antoine <contact@catenacyber.fr>
Date:   Sun Jun 16 20:20:43 2019 +0200

    No free in opt_init, rather in opt_cleanup

    (cherry picked from commit 35412e2a7f0e299f504608542730168fff022d66)

diff --git a/optimize.c b/optimize.c
index 5aa94d7d..1561c0b8 100644
--- a/optimize.c
+++ b/optimize.c
@@ -2166,8 +2166,6 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
        opt_state->n_edges = 2 * opt_state->n_blocks;
        opt_state->edges = (struct edge **)calloc(opt_state->n_edges, sizeof(*opt_state->edges));
        if (opt_state->edges == NULL) {
-               free(opt_state->blocks);
-               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }

@@ -2176,10 +2174,6 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
         */
        opt_state->levels = (struct block **)calloc(opt_state->n_blocks, sizeof(*opt_state->levels));
        if (opt_state->levels == NULL) {
-               free(opt_state->edges);
-               free(opt_state->blocks);
-               opt_state->edges = NULL;
-               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }

@@ -2190,12 +2184,6 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
        opt_state->space = (bpf_u_int32 *)malloc(2 * opt_state->n_blocks * opt_state->nodewords * sizeof(*opt_state->space)
                                 + opt_state->n_edges * opt_state->edgewords * sizeof(*opt_state->space));
        if (opt_state->space == NULL) {
-               free(opt_state->levels);
-               free(opt_state->edges);
-               free(opt_state->blocks);
-               opt_state->levels = NULL;
-               opt_state->edges = NULL;
-               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }
        p = opt_state->space;
@@ -2235,28 +2223,10 @@ opt_init(opt_state_t *opt_state, struct icode *ic)
        opt_state->maxval = 3 * max_stmts;
        opt_state->vmap = (struct vmapinfo *)calloc(opt_state->maxval, sizeof(*opt_state->vmap));
        if (opt_state->vmap == NULL) {
-               free(opt_state->space);
-               free(opt_state->levels);
-               free(opt_state->edges);
-               free(opt_state->blocks);
-               opt_state->space = NULL;
-               opt_state->levels = NULL;
-               opt_state->edges = NULL;
-               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }
        opt_state->vnode_base = (struct valnode *)calloc(opt_state->maxval, sizeof(*opt_state->vnode_base));
        if (opt_state->vnode_base == NULL) {
-               free(opt_state->vmap);
-               free(opt_state->space);
-               free(opt_state->levels);
-               free(opt_state->edges);
-               free(opt_state->blocks);
-               opt_state->vmap = NULL;
-               opt_state->space = NULL;
-               opt_state->levels = NULL;
-               opt_state->edges = NULL;
-               opt_state->blocks = NULL;
                opt_error(opt_state, "malloc");
        }
 }

